@@ -0,0 +1,36 @@
+/** Direct, allocation-light implementation of the frozen paired future-model policy. */
+import type { IDecisionContext } from "./ai_strategy";
+import type { GameAction } from "../engine/actions";
+import type { Unit } from "../units/unit";
+import { PBTypes } from "../generated/protobuf/v1/types";
+import { getCellForPosition } from "../grid/grid_math";
+
+export function selectA19BarrelForecast(
+    unit: Unit,
+    context: IDecisionContext,
+    beforeCleanup: GameAction[],
+    cleanup: GameAction[],
+): GameAction[] {
+    const sample = context.a19BarrelForecastSample;
+    if (!sample || sample.horizonMode !== "turns" || sample.rolloutCount !== 2 ||
+        (sample.sampleIndex !== 0 && sample.sampleIndex !== 1) ||
+        !Number.isInteger(sample.seedBase) || sample.seedBase < 0 || sample.seedBase > 0xffffffff ||
+        sample.sampleIndex !== (sample.seedBase & 1)) return cleanup;
+    if (context.decisionOrigin !== "rollout" || unit.getAttackTypeSelection() === PBTypes.AttackVals.RANGE ||
+        beforeCleanup === cleanup) return cleanup;
+    let hasIntent = false;
+    for (const action of beforeCleanup) {
+        switch (action.type) {
+            case "melee_attack": case "range_attack": case "area_throw_attack": case "cast_spell": case "obstacle_attack":
+                return cleanup;
+            case "move_unit": case "wait_turn": case "defend_turn":
+                hasIntent = true;
+        }
+    }
+    if (!hasIntent) return cleanup;
+    const strike = cleanup.find(action => action.type === "obstacle_attack");
+    if (!strike || strike.attackerId !== unit.getId()) return cleanup;
+    const cell = getCellForPosition(context.grid.getSettings(), strike.targetPosition);
+    return context.grid.getArtifactBarrels().some(barrel => barrel.cell.x === cell.x && barrel.cell.y === cell.y)
+        ? beforeCleanup : cleanup;
+}

